INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('kinnaras', 'Kinnaras', 'demon', 'rifts', 0, 'Diabolic (10%), Miscreant (15%) or Aberrant (75%)', '{"IQ":"1D6+12","ME":"1D6+12","MA":"1D6+10","PS":"1D6+24","PP":"1D6+16","PE":"1D6+16","PB":"1D6","Spd":"1D6+12"}', NULL, NULL, 'PEx10', 'PEx10', 'MEx4', 'Also known as Chin-na-lo. Race: a greater demon (the block prints no Race line). P.S. is Supernatural. M.D.C. +1D4x10 per level of experience; P.P.E. +1D6x10 per level. P.B. is 1D6 as the deformed killer and 1D6+16 in the divine horse-headed form. Horror Factor 15 is the deformed killer; the divine musician has Awe 12, +5 while it makes music. Sunlight halves attacks, combat bonuses, M.D.C., P.P.E. and I.S.P. Equivalent level 1D6. Always male. Killed at 30 M.D.C. below zero.', NULL, 15, '{"attacks":7,"strike":4,"parry":3,"dodge":1,"disarm":3,"pull":4}', 'The seven attacks are the deformed killer''s; a spell counts as two attacks. The divine artist has three attacks, or one by magic, and half the bonuses. +2 save vs all magic, +10 save vs Horror Factor, +6 save vs possession. Blade weapons: +2 strike and parry, +1 strike thrown; modern weapons with no bonus. Bone weapons it makes: femur cudgel +2 strike, +3 parry, +4 disarm; small club or hammer +2 strike, +2 parry, +1 disarm; dagger +2 strike, +1 parry, +2 disarm; spike +1 strike in hand, +2 thrown; Paired Weapons. Pleasant music in the background: -1 initiative and all combat bonuses.', 'Speaks all languages; reads Chinese and one language of choice 90%. Art 80%, Basic Math 90%, Calligraphy 90%, Dowsing 60%, Go 90%, History: China 80%, Land Navigation 70%, Lore: Demons and Monsters 70%, Lore: Religion 70%, Poetry 90%, Swim 90%, Whittling and Sculpture 75%, two Domestic or Technical skills of choice 65%. As the deformed killer: Horsemanship: Exotic Animals 80%, Intelligence 90%, Interrogation Techniques 80%, Concealment 70%, Pick Locks 70%, Prowl 80%, Streetwise 70%, Surveillance Systems (tailing only) 90%, Tracking (humanoids) 90%. In divine form: plays any instrument 98% (85% if unfamiliar), sings 90% +1% per level, Brewing, Cooking, Identify Plants and Fruits and Preserve Food 98%. Skills do not improve.', 'Both forms: immune to fire, poison, disease and S.D.C. weapons other than bone. Bio-regeneration: 3D6 M.D. each melee round (double at ley lines or wherever negative energy gathers), not at all in places of positive chi. A night hunter that rests three hours in 24 and can skip sleep for a week; by day it has two attacks fewer and -2 on combat bonuses. Flawless eyesight with a 180 degree field, twice the usual Nightvision range, infrared and ultraviolet, sees the invisible, and glare cannot blind it. Changing shape either way costs two attacks. Deformed killer: casts no shadow; shapes bone into M.D. cudgels, clubs, daggers and throwing spikes, and usually carries two large cudgels, two small clubs and 1D4+2 knives; spits bone blades up to 1000 ft (305 m), two in quick succession for a single attack. Divine horse-head: while it plays, no thinking creature can ignore the music or attack, and every fighter pauses; grows at will to 20 ft (6.1 m), its voice twice an opera singer''s at 10 ft (3 m), three times at 15 ft (4.6 m) and five times at 20 ft (6.1 m); becomes a black or white stallion, ordinary size or double, that runs at ten times its Spd, across water and on the wind up to 300 ft (91.5 m) high. VULNERABILITIES: outside the deformed body its attacks and bonuses are halved. An S.D.C. bone weapon does double its damage as M.D. to either form. Daylight halves attacks, bonuses, M.D.C., P.P.E. and I.S.P.; Globe of Daylight does so after one minute. Art, song and dance draw it, and lovely music distracts it. Full damage from magic, psionics and M.D. weapons.', 'Aura of Death (12), Befuddle (6), Call Lightning (15), Chameleon (6), Cloak of Darkness (6), Deathword (70), Death Trance (1), Dessicate the Supernatural (50), Energy Bolt (5), Extinguish Fire (4), Fire Ball (10), Frostblade (15), Havoc (70), Mental Shock (30), See in Magic Darkness (125), Sickness (50), Spoil (30). Demonic curses: Heritage, Wasting.', 'Major Psychic: Alter Aura (2), Bio-Manipulation (10), Deaden Senses (4), Ectoplasm (6+), Levitation (varies), Mind Block (4), Sense Time (2), Sixth Sense (2)', '6-7 ft (1.8 to 2.1 m) as the deformed killer; 9-12 ft (2.7 to 3.6 m) in divine form', '200 lbs (90 kg) as the deformed killer; 600 lbs (270 kg) in divine form', 'Presumed immortal', 'China and Korea, at times Russia and Japan; a master may send it anywhere on Earth or beyond', 'Leads lesser demons and monsters and works beside other greater demons; yields to the Demon Lords and reveres the Kou Ching and Shen Wu. Most are loyal soldiers', 'Humans are prey and toys, as is anyone in its way or named by its master. Dislikes pranksters such as the Fox Spirit and Monkey Spirit, and treats the Fox Faerie as a rival', NULL, 'A demon with two bodies: a four-eyed, misshapen killer and spy that eats what it kills, and a handsome horse-headed musician and cook that it wears to please gods and masters. It serves as squad leader and assassin, and nobody can strike a blow while it plays.', 'Rifts World Book 24: China 1 p.106-108'),
('kou-ching', 'Kou Ching', 'demon', 'rifts', 0, 'Aberrant (100%)', '{"IQ":"1D6+12","ME":"1D6+16","MA":"1D6+14","PS":"1D6+30","PP":"1D6+16","PE":"1D6+20","PB":"1D6+18","Spd":"1D6+30"}', NULL, NULL, 'PEx100', 'PEx10', 'MEx3', 'Also known as the Dog Spirit. Race: a greater demon (the block prints no Race line). P.S. is Supernatural. M.D.C. +5D6x10 per level of experience; P.P.E. +1D6x10 per level. Spd is about 22 mph (35 km), tripled as a hunting dog. Water halves M.D.C., P.P.E., Spd, bonuses and attacks. Equivalent level 1D6+3. Always male. Between zero and 30 M.D.C. below zero it becomes a pearl for 24 hours and comes back whole; at 31 or more below zero it is destroyed, spends a year in limbo and two more as a mortal feral wolf (1D6x10+16 Hit Points, 1D6x10 S.D.C.), then returns as a demon of third level.', NULL, 16, '{"attacks":9,"strike":3,"parry":3,"dodge":1,"disarm":3,"pull":4}', 'A spell counts as three attacks. +2 save vs all magic, +10 save vs Horror Factor, +6 save vs possession. Blade weapons: +2 strike and parry, +1 strike thrown; modern weapons with no bonus. With its fire swords: +1 initiative, +2 strike, +3 parry, +3 disarm, +5 pull. Foes inside its smoke are -4 to strike, parry and dodge. As a feral wolf: four attacks, +3 strike, +1 parry, +4 dodge.', 'Speaks all languages; reads Chinese, Hindu/Indian and one language of choice 90%. Art 80%, Basic Math 98%, Calligraphy 90%, Dowsing 60%, Go 90%, History: China 80%, Lore: D-Bees 70%, Lore: Magic 70%, Prowl 50%, Land Navigation 90%, two Domestic or Technical skills of choice 70%. Skills do not improve.', 'Sharp sight, Nightvision 400 ft (122 m), sees the invisible. Teleports between dimensions at 50%, +5% a level. Immune to fire, poison, disease and S.D.C. weapons other than silver; man-made M.D. weapons and explosives do half damage. Bio-regeneration: 4D6 M.D. each melee round (double at ley lines or wherever negative energy gathers), not at all in places of positive chi. Rests two hours in 24, can skip sleep for a week, and goes about by day. Summons up to three Lesser Demons or Goblins (never Fox Spirits) once in 24 hours, 01-74% +2% per level, for 2-6 hours as a rule. Hunting dog form: tracks by smell 86%, +10% on blood. Pearl form: cannot be broken, senses a 15 ft (4.6 m) radius, cannot attack and heals at half speed; alcohol halts the healing and shuts its senses. Spits pearl cannon balls 3000 ft (914 m), one attack each. Smoke breath, two attacks: a 40 ft (12.2 m) radius cloud up to 200 ft (61 m) away. A pair of magic swords comes to hand at will (one attack) and each bursts into flame for one attack; a sword shoots fire bolts 2000 ft (610 m), both together for double damage and two attacks, and flies back when thrown up to 1000 ft (305 m). Grows at will from 6 ft (1.8 m) to 20 ft (6.1 m). VULNERABILITIES: water, even knee deep or rain heavier than a drizzle, halves it as above. Double damage from holy and demon-slaying weapons and from those a god of Light has blessed; a vial of holy water does 1D6 M.D. S.D.C. silver does its damage as M.D. and takes twice as long to heal. Full damage from magic, magic weapons and psionics. Drink affects it and it can get drunk. The swords vanish when it is destroyed or becomes a pearl.', 'Anti-Magic Cloud (140), Ballistic Fire (25), Dessicate the Supernatural (50), Dispel Magic Barrier (20), Electric Arc (8), Enchant Weapon (400+), Fire Ball (10), Fire Blossom (20), Fire Gout (20), Lightning Arc (30), Mask of Deceit (15), Meteor (75), Negate Magic (30), Phantom Mount (45), See in Magic Darkness (125), Swords to Snakes (50), Teleport (600), Transferal (50), Words of Truth (15). Through the swords, each once per 24 hours on its own P.P.E.: Extinguish Fire (8), Fire Whip (30), Heal Burns (15), Globe of Daylight (2), Plasma Bolt (60), See Through Smoke (12), Wall of Flame (15). Demonic curses: none.', 'Major Psychic: Mind Block Auto-Defense (special), Object Read (6), Mask P.P.E. (4), See Aura (6), Sense Time (2), Telepathy (4)', '6-7 ft (1.8 to 2.1 m) man-sized; 15-20 ft (4.6 to 6.1 m) divine, changing with its opponent', '200 lbs (90 kg) man-sized; 2000 lbs (900 kg) divine', 'Presumed immortal; a slain one returns after three years, two of them as a wolf', 'Anywhere on Earth and beyond: several hundred in China, a few dozen in Southeast Asia, never more than three thousand in all', 'Its hunt serves the dark gods, Demon Lords and Yama Kings, yet it seldom sides with any one of them; it may ask other evil beings for word of a hero', 'Every Champion of Light, avatar and servant of the Celestial Court, and mortal heroes; dragons and True Atlanteans. It eats humans, the young above all', NULL, 'A dog-headed greater demon, close to a Demon Lord in power, that roams in search of champions of light to duel to the death. It fights with a pair of flaming swords, spits pearls like cannon shot and can turn into a hound or an unbreakable pearl.', 'Rifts World Book 24: China 1 p.108-112'),
('mahoragas', 'Mahoragas', 'demon', 'rifts', 0, 'Miscreant (40%), Diabolic (50%) or Aberrant (10%)', '{"IQ":"1D6+20","ME":"1D6+18","MA":"1D6+20","PS":"1D6+19","PP":"1D6+14","PE":"1D6+19","PB":"1D6+4","Spd":"1D6+10"}', NULL, NULL, '1D4x100', '2D4x10+90', 'MEx10', 'Also known as the Serpent. Race: a greater demon. P.S. is Supernatural. M.D.C. +4D6 per level of experience. Spd is unchanged in small snake form. Equivalent level 1D6+1. Male or female, 50% each. Between zero and 10 M.D.C. below zero it breaks into a dozen small green worms and is whole again, at full M.D.C., in 10 minutes (spent P.P.E. and I.S.P. do not come back). Killed only when taken past 10 below zero, beheaded, the head hung in a tree and the body buried.', NULL, 14, '{"attacks":4,"strike":1,"parry":1,"dodge":3}', 'The dodge is automatic. A spell counts as two attacks. +2 save vs all magic, +8 save vs Horror Factor, +6 save vs possession; its P.E. adds a large bonus to save vs magic. As a boa: +5 to entangle. As a cobra: +1 initiative, +1 attack, +2 strike, +1 dodge. It never uses a weapon.', 'Speaks all languages; reads Chinese, Hindu/Indian and one language of choice 95%. Anthropology 80%, Basic Math 98%, Calligraphy 90%, Dowsing 90%, Find Contraband 65%, Gemology 75%, Holistic Medicine 70%, History: China 80%, Lore: Demons and Monsters 80%, Lore: Magic 60%, Lore: Psychics and Psionics 80%, Prowl 45%, Land Navigation 65%, Seduction 80%, two Technical or Science skills of choice 50%. As a small snake: Swim 95%, Prowl 75%, Climb 95%/90%. Skills do not improve.', 'Sharp sight, Nightvision 400 ft (122 m), sees the invisible. Teleports between dimensions at 30%, +5% a level. Immune to cold, poison, disease and S.D.C. weapons; man-made M.D. weapons and explosives do half damage. Bio-regeneration: 2D6 M.D. each melee round (double at ley lines or wherever negative energy gathers), not at all in places of positive chi. Shows itself by day or night, though daylight leaves it exposed. Snake form: an ordinary-looking large cobra or boa that slips through small gaps, still talks and uses psionics but casts no spells; returning to the giant shape takes one attack. A boa pins the limbs of what it coils around, and only an ordinary P.S. three times its own, or a Supernatural P.S. 10 or more above it, breaks loose; each squeeze is one attack. A cobra''s bite does 1D6 M.D. extra. VULNERABILITIES: its snake shape scares people. Full damage from magic, magic weapons and psionics, half from most other M.D. weapons. Double damage from Millennium Tree weapons and wands, from magic weapons made to slay serpents or dragons, and from a true dragon''s breath or bite. A mongoose is Horror Factor 15 to it, and on a failed save it flees 01-60% of the time; a real one claws for 5D6 M.D. and bites for 1D6x10 M.D., stops its regeneration within 100 yards (91 m), is immune to its psionics, and takes only 10% of its damage, as S.D.C.', 'Agony (20), Astral Projection (10), Calling (8), Charm (12), Commune with Spirits (25), Compulsion (20), Domination (10), Eyes of Thoth (8), Forcebonds (25), Instill Knowledge (15), Locate (30), Oracle (30), Mute (50), Second Sight (20), See Aura (6), See Wards (20), Swords to Snakes (50), Transferal (50), Words of Truth (15). Demonic curses: none.', 'Master Psychic: Alter Aura (2), Clairvoyance (4), Detect Psionics (6), Group Trance (15), Hypnotic Suggestion (6), Mind Block Auto-Defense (no cost printed), Object Read (6), Mask I.S.P. and Psionics (7), Mask P.P.E. (4), Mentally Possess Others (30), Presence Sense (4), Psychic Body Field (30), Psychic Diagnosis (4), Psychic Omni-Sight (15), Psychosomatic Disease (30), See Aura (6), Sense Dimensional Anomaly (4), Sense Time (2), Telemechanics (10), Telepathy (4)', '15-20 ft (4.6 to 6.1 m); looks smaller coiled', '1000-2000 lbs (450 to 900 kg)', 'Presumed immortal', 'China, India and Southeast Asia, rarely anywhere else; one or two are rumoured in the African Congo', 'Its own kind, and now and then other demons or gods of war and chaos; chaos is its only real cause. Forced into service, it helps heroes and traitors bring its captor down', 'The Yama Kings. Humans are pawns and toys; it feels kinship with no one, keeps to itself, and 90% are bitterly jealous of true dragons', NULL, 'A giant boa with human eyes that catches glimpses of the future and trades its counsel for favours, secrets or food. It serves chaos, steering mortals into toppling rulers and founding cults, and it is terrified of the mongoose.', 'Rifts World Book 24: China 1 p.112-114'),
('monkey-spirit', 'Monkey Spirit', 'demon', 'rifts', 0, 'Any; most are Unprincipled (30%), Anarchist (45%), Miscreant (10%) or Aberrant (5%)', '{"IQ":"1D6+16","ME":"1D6+15","MA":"1D6+17","PS":"1D6+17","PP":"1D6+16","PE":"1D6+15","PB":"1D6+9","Spd":"1D6+15"}', NULL, NULL, '3D6x10+PE', '1D6x10+40', 'MEx2', 'Race: a greater supernatural being/demon. P.S. is Supernatural. M.D.C. +2D6+20 per level of experience. A spell caster has a further 1D6x10 P.P.E. and +10 per level. Spd is doubled climbing or swinging through trees. The book calls its 11 a Horror/Awe Factor. Equivalent level 1D6+1. Male or female, 50% each. Killed at 50 M.D.C. below zero; a peach pit in the mouth bars magical Resurrection and Restoration.', NULL, 11, '{"attacks":5,"initiative":2,"strike":1,"parry":1,"dodge":2,"pull":3,"roll":3}', 'The dodge is automatic. Two attacks per melee by magic. +1 save vs all magic, +3 save vs illusions, +3 save vs Horror Factor and possession. Favours knives and staves; guns with no bonus. The tail wields ancient weapons at half bonuses and guns at -4.', 'Speaks all languages; may read one or two (taken as Technical skills). Acrobatics 90%, Calligraphy 75% (only if it can read), Climb 98%/90%, Dance 80%, Escape Artist 75%, Gambling 75%, Land Navigation 75%, Swim 50%, W.P. Knife or Staff, three Rogue skills of choice 75%, 1D4+1 Technical skills of choice 70%. Skills do not improve.', 'Nightvision 600 ft (183 m), sees the invisible. Teleports between dimensions at 25%, +5% a level. Leaps 10 ft (3 m) up and 20 ft (6.1 m) across; scales buildings and steep slopes at running speed, 70% +2% per level. Immune to disease and to most S.D.C. weapons. Bio-regeneration: 2D6 M.D. each melee round (double at ley lines or wherever positive energy gathers); a good one does not heal at all in places of negative chi. As active by night as by day; sleeps about five hours in 24. Its prehensile tail holds and carries things and does skills at half proficiency in twice the time. VULNERABILITIES: S.D.C. weapons of ice, peach-tree wood or iron do their damage as M.D.; ice spells and ice magic weapons do 50% more. It cannot resist peaches: 12 or more of the fruit, or 3-6 pies or bottles of peach jam or wine, will buy its help. Full damage from psionics, magic weapons and most magic.', 'Only half cast spells; one that does knows 8 spells +2 per level of experience, chosen from Invocation levels 1-7. The book prints no spell list. Demonic curses: none.', 'Minor Psychic: Empathy (4), Sense Time (2), Telepathy (4), Mind Block (4)', '5-6 ft (1.5 to 1.8 m); it crouches and looks shorter', '90-130 lbs (40.5 to 58.5 kg)', 'Unknown; at least 1000 years, perhaps immortal', 'China and Southeast Asia, forests and mountains most of all; now and then Mongolia, Russia, Japan and India', 'Fond of humans, it often travels and sides with them for fun, adventure or profit, and a true friend has a loyal companion', 'Mortals and demons alike find it a nuisance, though either may put up with it for its help or advice', NULL, 'A man-sized talking monkey of flesh and blood that lives as a trickster, thief and friend of the downtrodden. Cocky and curious, it stumbles into trouble as often as it causes it, and peaches are its great weakness.', 'Rifts World Book 24: China 1 p.114-116'),
('naga', 'Naga', 'demon', 'rifts', 0, 'Any; mostly Anarchist (35%), Miscreant (10%), Diabolic (10%) or Aberrant (35%)', '{"IQ":"1D6+24","ME":"1D6+22","MA":"1D6+20","PS":"1D6+30","PP":"1D6+14","PE":"1D6+19","PB":"1D6+4","Spd":"1D6+10"}', NULL, NULL, '1D6x100', 'PEx100', 'MEx6', 'Also known as the Dragon''s Little Sister. Race: a greater demon, a distant cousin of the dragon. P.S. is Supernatural. M.D.C. +3D6x10 per level of experience; P.P.E. +1D6x100 per level of experience. Spd is on land; underwater it is 1D6x10+44, doubled when she rides the current. Equivalent level 1D6+4. 80% are female. At 60 M.D.C. below zero she lies inert and ice-cold, then rises whole with the next evening mist or fog, bent on revenge; only one pound of melted silver or of salt poured into her mouth ends her, turning her to a mist of droplets. The introduction gives the length as 12-30 ft; the stat block''s figure is used.', NULL, 16, '{"attacks":6,"initiative":2,"strike":4,"parry":2,"dodge":5}', 'A spell counts as two attacks. The parry is made with tail or neck. The dodge is automatic, though the D20 is still rolled. +3 save vs all magic, +4 save vs mind control, +10 save vs Horror Factor; immune to possession.', 'Speaks all languages; reads all Chinese languages, Hindu/Indian and one language of choice 96%. Astronomy 90%, Basic Math 98%, Dance 80%, Dowsing 90%, Gemology 80%, History: China 90%, Lore: Animals (aquatic only) 90%, Lore: Demons and Monsters 80%, Lore: Magic 70%, Navigation 95%, Prowl 50% (+20% underwater), Seduction 80%, two Domestic and two Science skills of choice 75%. Skills do not improve.', 'Keen sight, nightvision 3000 ft (914 m), sees the invisible and through dark or murky water. Needs no air, so a vacuum cannot harm her. Unseen whenever she wishes in rain or fog. Dimensional teleport 20% +5% per level. Immune to S.D.C. weapons other than silver or ice, and to cold, poison, disease, electricity and lightning; explosives and man-made M.D. weapons do half damage. Bio-regeneration: 4D6 M.D. each melee round (double at ley lines or wherever negative energy gathers), not at all in places of positive chi. Abroad by day or night. Human form at will, for as long as she likes: attractive, of any age, black-haired and green-eyed, P.B. 20 at least. Size change at will: the human shape doubles from 5-6 ft (1.5 to 1.8 m) to 10-12 ft (3 to 3.6 m); the serpent holds 30 ft (9.1 m) indefinitely and as much as 60 ft (18.3 m) for an hour at most, and from 50 ft (15.2 m) upward her M.D.C., bite damage and lightning range grow by 50%. Spits lightning out to 3000 ft (914 m), one attack a bolt: 2D6 M.D. as a warning, 6D6 M.D. in earnest. Fog breath, two attacks: a cloud of 100 ft (30.5 m) radius placed up to 200 ft (61 m) away, its radius doubling with every full round she keeps breathing, to a limit of one mile (1.6 km) per level; inside it sight ends at 3 ft (0.9 m), close combat is at -2 on every roll, shadows out to 9 ft (2.7 m) are at -6 to strike, parry and dodge, and she herself cannot be seen. Dives 1000 ft (305 m) in one action and no depth harms her. Rides the wind: hovers on a light breeze, takes storm winds above 30 mph (48 km) unhurt, travels 40-90 mph (64 to 144 km) in a rainstorm and as fast as 240 mph (384 km) in a hurricane or Ley Line Storm, provided she keeps ahead of the storm and on the line. Calls weather through her magic. Every 12 hours she can summon up to a dozen Water Goblins and up to three Water Devils (Hsia Yu). VULNERABILITIES: quick-tempered and unpredictable. Silver or ice: S.D.C. weapons do their damage as M.D. and M.D. weapons double. M.D. fire, spells included, does 50% more. Six hours or more in hot, arid country halves her M.D.C., bio-regeneration and bonuses. Magic, psionics and magic weapons do normal damage; most other M.D. weapons half.', 'All Water Elemental Magic. Invocations: Anti-Magic Cloud (140), Call Lightning (15), Cleanse (6), Desiccate the Supernatural (50), Enchant Weapon (400+), Expel Demons (35), Greater Healing (30), Lightning Arc (30), Mystic Portal (60), Negate Magic (30), Negate Poison (5), Protection Circle: Simple (45), Protection Circle: Superior (300), Purge Other (100), Remove Curse (140), Restore Limb (80), Rift to Limbo (160), Rift Teleportation (160), Seal (7), Speed of the Snail (50), Summon Fog (140), Swim as the Fish: Superior (12, cast on others), Teleport: Lesser (15), Teleport: Superior (600), Water to Wine (40). Demonic curses: Drought, Forefather, Heritage, Interesting Life.', 'Master Psychic: Alter Aura (2), Empathy (4), Hydrokinesis (varies), Mind Block (4), Mind Bond (10), Object Read (6), Psychic Omni-Sight (15), Telepathy (4; free with Water Goblins, Water Demons, other Naga, Water Dragons and Water Elementals)', '15-30 ft (4.6 to 9.1 m) long; rears its head 7-15 ft (2.1 to 4.6 m)', '2000-4000 lbs (900 to 1800 kg)', 'Presumed immortal', 'China, India and Southeast Asia; rarely elsewhere', 'Water Goblins and Water Devils; other lesser demons and creatures as minions; snake cults, a third or more of which worship her. A loner by habit', 'Whoever challenges, defies or attacks her, and above all anyone who tries to enslave her. Hates slavers, the Horune Pirates among them; dislikes Mahoragas; treats Water Dragons and other strong aquatic beings as rivals', NULL, 'A great serpent of rain, rivers and sea with a woman''s face and a cobra''s hood. She tries mortals with disasters and challenges, cannot be coerced, and follows nothing but her own whim.', 'Rifts World Book 24: China 1 p.116-121'),
('naga-spawn', 'Naga-Spawn', 'supernatural', 'rifts', 1, 'Any; most lean to Principled, Scrupulous, Unprincipled or Anarchist', '{"IQ":"3D6+1D6","ME":"3D6+1D6","MA":"3D6+2D6","PS":"3D6+2D6","PP":"3D6+1D6","PE":"3D6+1D6","PB":"3D6+1D6","Spd":"3D6+1D6"}', NULL, NULL, 'PEx3', NULL, NULL, 'A half-Naga raised as a human. The book prints attribute bonuses over a human (+1D6 to all, +2D6 to M.A. and P.S.), stored here on the human 3D6. P.S. is Supernatural. +2D6 M.D.C. per level of experience, in place of Hit Points and S.D.C. Otherwise rolled up as an ordinary human, with O.C.C., skills and alignment chosen as usual. A G.M. may use one as a villain or NPC, or allow it as a player character in a campaign of Heroes of the Celestial Court, at the G.M.''s option. Under 10,000 exist at any one time.', NULL, NULL, '{}', NULL, 'Skills and knowledge come from the character''s human O.C.C.', 'Immune to disease. Swims by instinct at 98% and holds its breath one minute per point of P.E. M.D. lightning and electricity do half damage. Bio-regeneration: 1D6 M.D. every minute (one point per melee round). Sees clearly through mist and fog, and can turn invisible in fog. Feels rain coming and knows whether it will fall light or heavy. VULNERABILITIES: once a sorcerer, creature of magic or supernatural being learns its true name, the spawn loses every bonus to save vs that foe''s magic, psionics or poison, and its remaining bonuses are halved. Most S.D.C. weapons cannot hurt it, yet those of silver or ice, or coated with either, do their damage as M.D. M.D. fire does 50% more; cold does none; other M.D. attacks do normal damage.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The human-looking child of a Naga mother, left with monks or foster parents to be brought up as one of them. Its toughness and its kinship with water show in the teens, and at 14-16 it usually sets out as a hero or a villain.', 'Rifts World Book 24: China 1 p.118'),
('water-goblin', 'Water Goblin', 'demon', 'rifts', 0, 'Anarchist (50%) or Aberrant (50%)', '{"IQ":"1D6+5","ME":"1D6+7","MA":"1D6+6","PS":"1D6+7","PP":"1D6+10","PE":"1D6+10","PB":"1D6+8","Spd":"1D6+10"}', NULL, NULL, '2D6+PE', NULL, 'MEx2', 'P.S. is Supernatural. Spd is running; swimming is double, and faster still on a current of wind or water under its magic umbrella. Printed inside the Naga''s summoning abilities rather than as its own entry: she summons up to a dozen every 12 hours. The book prints no Horror Factor, size, damage or bonuses for it.', NULL, NULL, '{"attacks":2}', 'Not a fighter.', 'Speaks all languages; reads Chinese 90%.', 'Needs no air. Its yellow umbrella catches wind or water and carries it along at twice the speed of the current, and it rides colts at double speed too; as a messenger it covers 1000 miles (1600 km) in a day.', 'None beyond the umbrella.', 'Minor Psychic: Mind Block (4), Levitation (varies), Total Recall (free, and only for the message it carries)', NULL, NULL, NULL, 'Waters where Naga, water dragons and other supernatural beings live, chiefly in China, India and Southeast Asia', 'Serves the Naga and other great water beings', NULL, NULL, 'A tiny, spindly attendant in yellow clothes and cap that carries a yellow umbrella. It exists to wait on the Naga and other powers of the water and to run their messages.', 'Rifts World Book 24: China 1 p.119-120'),
('water-devil', 'Water Devil', 'demon', 'rifts', 0, 'Anarchist (30%), Miscreant (20%) or Aberrant (50%)', '{"IQ":"1D6+8","ME":"1D6+8","MA":"1D6+6","PS":"1D6+10","PP":"1D6+12","PE":"1D6+12","PB":"1D6+4","Spd":"1D6+10"}', NULL, NULL, '4D6+PE', 'PEx3', 'MEx2+12', 'Also known as the Hsia Yu. P.S. is Supernatural. Spd is running; flying is 1D6+22 and swimming 2D6+66. Printed inside the Naga''s summoning abilities rather than as its own entry: she summons up to three every 12 hours. Wild ones run in schools of 1D6+2. The book prints no Horror Factor, size or damage for it.', NULL, NULL, '{"attacks":5,"initiative":1,"strike":2,"parry":4,"dodge":2,"disarm":2,"pull":4}', NULL, 'Speaks all languages.', 'Needs no air. Hovers and flies as high as 20 ft (6.1 m) over ground or water. Takes the shape of a small Nurse Shark.', 'Cleanse (6), Energy Bolt (5), Escape (8), Lantern Light (1), Influence the Beast (12, sea life only), Magic Shield (6), Mystic Alarm (5), Orb of Cold (6), Repel Animals (7, aquatic only).', 'Major Psychic: Mind Block (4), Empathy (4), Telepathy (4; free with the Naga, Water Goblins and its own kind)', NULL, NULL, NULL, 'Seas, rivers and lakes, never swamps, of China, India and Southeast Asia, wherever Naga, water dragons and their like live', 'Serves the Naga and other greater aquatic beings as groom, guard and errand-runner', 'Wild schools plague sailors and fishermen: they steal fish and crabs, cut nets, climb aboard ships and shove people into the water', NULL, 'A child-sized, black-skinned water servant with webbed limbs, a shark''s teeth, red eyes and ears like fins. Most wait on the Naga, while those running wild make mischief for anyone working the water.', 'Rifts World Book 24: China 1 p.120'),
('red-child-demon', 'Red Child Demon', 'demon', 'rifts', 0, 'Diabolic (50%) or Miscreant (50%)', '{"IQ":"1D6+14","ME":"1D6+14","MA":"1D6+18","PS":"1D6+24","PP":"1D6+15","PE":"1D6+16","PB":"1D6+22","Spd":"1D6+20"}', NULL, NULL, 'PEx10', '6D6x10', 'MEx2', 'P.S. is Supernatural. M.D.C. +15 per level of experience; P.P.E. +1D4x10 per level of experience. The 15 stored as Horror Factor is the Awe Factor of its child guise; the book prints no separate Horror number and has the roll made again, as horror, when the treachery comes out. Sunlight and daytime halve its attacks, combat bonuses, M.D.C., P.P.E. and I.S.P., and Globe of Daylight does so after one minute unless it is in human guise. Equivalent level 1D6. Any gender, 70% appearing male. Killed at 30 M.D.C. below zero, short of which it regenerates in minutes; nine months on it is born again as a demon child, knows what it is by 13 and keeps only dim memories.', NULL, 15, '{"attacks":6,"initiative":1,"strike":3,"parry":3,"dodge":2,"disarm":1,"pull":3}', 'A spell counts as three attacks. +2 save vs all magic, +9 save vs Horror Factor; immune to possession. Man-made weapons with no W.P. bonuses.', 'Speaks all languages; reads Chinese 80%. Basic Math 90%, Calligraphy 70%, Concealment 80%, Dance 80%, Escape Artist 90%, History: China 80%, Intelligence 70%, Interrogation Techniques 70%, Land Navigation 80%, Lore: Law 70%, Lore: Religion 90%, Palming 80%, Poetry 90%, Performance 90%, Prowl 70%, Seduction 50%, Streetwise 80%, Swim 80%, Tracking (humanoids) 80%, Ventriloquism 90%, two Domestic or Technical skills of choice 70%. Skills do not improve.', 'Nightvision 1000 ft (305 m). Immune to S.D.C. weapons other than stone or bone, and to cold, poison and disease. Bio-regeneration: 3D6 M.D. each melee round (double at ley lines or wherever negative energy gathers), not at all in places of positive chi. Can go out by day, weakened. Rests 2-3 hours in 24 and can skip sleep for a week at no penalty. Human form: any person, man or woman, from small child to aged elder, including a flawless copy of anybody it has met who touched it, though without that person''s memories or knowledge; See Aura, psionics and probing magic all fail to expose it. It favours children under 8 and the very old. Red Cloud: makes a small red cloud the size of a sofa or bath tub and steps inside, seeming to vanish; from it the demon sees and hears out to 300 yards, floats at half its Spd as high as about 100 ft (30.5 m), can neither strike nor be struck, may be blown off by wind, and must take solid form again to attack. VULNERABILITIES: once it picks a victim it cannot let go, and tries again and again until it wins or dies. Blind to red, which it sees as grey or green, so it never notices the red sky, moon or cloud that warns mortals. S.D.C. weapons of stone or bone do their damage as M.D. Weak in daylight (see the pools note). Magic, psionics and M.D. weapons do normal damage.', 'Blinding Flash (1), Calling (8), Chameleon (6), Charismatic Aura (10), Chromatic Protection (10), Climb (3), Cloud of Smoke (2), Electric Arc (8), Energy Bolt (5), Energy Disruption (12), Fear (6), Fire Bolt (7), Float in Air (5), Fly (15), Frequency Jamming (15), Invisibility: Simple (6), Heavy Air (200), Manipulate Objects (2+), Mask of Deceit (15), Multiple Image (7), Reflection (7), Swim as a Fish (6), Thunder Clap (4), Wall of Wind (40), Wind Rush (20). Demonic curses: Heritage, Wasting.', 'Minor Psychic: Levitation (varies), Mind Block (4), Presence Sense (4), Telekinetic Leap (8), Telekinetic Punch (6)', 'Any, from a child of 3-12 years to a 6 ft (1.8 m) adult', 'Varies with size', 'Presumed immortal; said to come back nine months after death as a boy born at midnight under a full red moon, who turns demon at puberty', 'China and Korea, at times Russia and India; a master may send it anywhere on Earth or beyond', 'Fellow tricksters (Kinnaras, Fox Faeries, Fox Spirits, Monkey Spirits, Goblins); serves the Yama Kings and dark powers as henchman and assassin. A loner and a poor leader. It never harms a child and may protect one', 'Humans are prey and toys; it kills whoever blocks its way or whom its master names. Hates the pious and religious, dislikes the heroic and helpful', NULL, 'A killer that passes for an innocent child, or for someone it has touched, to draw its victims to a treacherous end, the pious and the heroic above all. It bathes in blood, and a faint red tint in sky, cloud or moon gives its presence away.', 'Rifts World Book 24: China 1 p.121-123'),
('shen-wu', 'Shen Wu', 'demon', 'rifts', 0, 'Diabolic (30%) or Aberrant (70%)', '{"IQ":"1D6+24","ME":"1D6+18","MA":"1D6+18","PS":"1D6+34","PP":"1D6+18","PE":"1D6+18","PB":"1D6+11","Spd":"1D6+22"}', NULL, NULL, '1D6x100', '1D4x100', 'MEx3', 'Also known as the Wise Warrior. P.S. is Supernatural. M.D.C. +1D6x10 per level of experience; P.P.E. +1D6x10 per level of experience. As a raven it flies 30 mph (48 km); as a whirlwind 400 mph (640 km) in the air and half that along the ground, no higher than 30,000 ft (9144 m). Equivalent level 1D6+2. Always male. Killed at 100 M.D.C. below zero, short of which it regenerates in minutes.', NULL, 15, '{"attacks":12,"initiative":4,"strike":6,"parry":6,"dodge":2,"disarm":4,"pull":6}', 'A spell counts as four attacks. +2 save vs all magic, +8 save vs Horror Factor and possession. Any spear or staff: +3 strike, +3 parry, +3 strike thrown. Every other weapon, guns and modern arms included: +1 strike and parry. As a raven it has half its attacks.', 'Speaks all languages; reads all Chinese languages 98% and two foreign languages 90%. Basic Math 98%, Calligraphy 90%, Dance 90%, History: China 98%, Holistic Medicine 70%, Intelligence 80%, Interrogation Techniques 70%, Land Navigation 98%, Acrobatics 90%, Climb 98%/95%, Boxing and Wrestling (no percentage printed), Swim 98%, Track Animals 80%, Tracking (humanoids) 80%, three Science and three Technical skills of choice 80%; Computer Operation, Radio: Basic, Basic Mechanics, Demolitions, Horsemanship: Exotic, Military Etiquette, Recognize Weapon Quality, Trap/Mine Detection, Law and all Lores 95%. Skills do not improve.', 'Sight that carries 5 miles (8 km); nightvision 6000 ft (1829 m). Immune to S.D.C. weapons other than jade-inlaid ones, and to cold, poison and disease. Bio-regeneration: 1D4x10 M.D. each melee round (double at ley lines or wherever negative energy gathers), not at all in places of positive chi. Abroad day or night; rests 2-3 hours a day and can skip sleep for a week at no penalty. Size at will from 7 ft (2.1 m) to 28 ft (8.5 m). Spits green lightning to 2000 ft (610 m), one attack a bolt. Raven form: a big black raven or crow whose beak and claws do only 2D6 M.D. Whirlwind form, green-grey: foes fight it with half their combat bonuses and attacks; projectiles and energy blasts do half damage and explosions a third; a physical blow does half, and the one who lands it is caught and flung 100 yards, losing initiative and 1D4+1 attacks and taking 4D6 M.D., or 1D6 M.D. on a successful roll with impact, though anyone with automatic dodge, acrobatics or gymnastics may try to kick clear. Its own whirlwind strike does 6D6+6 M.D. and throws the target 100 yards with the same losses (3D6 M.D. on a save); the power slam, two attacks, does 2D4x10 M.D. and throws 200 yards. VULNERABILITIES: M.D. fire does double damage, triple to the whirlwind. Over 30 minutes in heat of 90 degrees Fahrenheit or more halves its P.S. and P.P.E., cuts M.D.C., Spd and attacks by 30% and slows its healing to 3D6 a round. S.D.C. weapons made of jade or inlaid with it, whether green, brown or white, do their damage as M.D. In solid form magic, psionics and M.D. weapons do normal damage.', 'Air Elemental: Ball Lightning (15), Darken the Sky (25), Dissipate Gases (15), Electrical Field (35), Electro-Magnetism (40), Frequency Jamming (8), Lightblade (12), Sheltering Force (10), Stop Wind (5), Thunder Clap (2), Walk the Wind (10), Wind Blast (40), Wind Cushion (50), Wind Rush (10), Whisper of the Wind (30), Whirlwind (30). Invocations: Banishment (65), Blinding Flash (1), Calling (8), Chromatic Protection (10), Collapse (70+), Commune with Spirits (25), Disharmonize (150), Electric Arc (8), Energy Bolt (5), Energy Disruption (12), Eyes of Thoth (8), Fists of Fury (10+), Forcebonds (25), Implosion Neutralizer (12), Instill Knowledge (15), Ley Line Time Capsule (15), Ley Line Transmission (30), Negate Mechanics (20), Plane Skip (65), Power Bolt (20), Rift Teleportation (200), See in Magic Darkness (125), Speed Weapon (100), Swap Places (300), Time Hole (210), Watchguard (10). Demonic curses: Heritage, Interesting Life, Rags.', 'Major Psychic: Levitation (varies), Mind Block (4), Presence Sense (4), Sense Magic (3), Speed Reading (2), Total Recall (2)', '20 ft (6.1 m) by nature; any height from 7 to 28 ft (2.1 to 8.5 m)', '5000 lbs (2250 kg) at natural size; always 100 lbs (45 kg) heavier than it looks', 'Presumed immortal', 'Mainly China and Korea, at times Russia and India; a master may send it anywhere in the Megaverse', 'Serves in the armies of greater beings, often as a commander; several Yama Kings field some and a few a whole legion. With its master dead it wanders Asia as it pleases', 'Whoever challenges or attacks it and whoever its master names, old allies, heroes and avatars of the gods included; otherwise it keeps to itself', NULL, 'A blue-skinned, four-armed giant with eyes of flame and hair of green fire, a soldier who is a scholar as well. It counsels the polite and patient honestly, yet obeys its dark master and kills fast and without cruelty.', 'Rifts World Book 24: China 1 p.123-126'),
('white-monkey', 'White Monkey', 'demon', 'rifts', 0, 'Anarchist (15%), Miscreant (35%) or Diabolic (50%)', '{"IQ":"1D4+4","ME":"1D6+6","MA":"1D6","PS":"1D6+34","PP":"1D6+15","PE":"1D6+20","PB":"1D6+6","Spd":"1D6+12"}', NULL, NULL, '3D6x10+280', '1D6x10+PE', NULL, 'Also known as the Demon Monkey. Race: a greater demon, on raw power alone. P.S. is Supernatural. Equivalent level 1D4+1. Always male. Killed at 50 M.D.C. below zero, or by cutting off its head and throwing that into a river or lake, where it dissolves; a head thrown into a swamp or stagnant water grows into two White Monkeys with half the I.Q. and double the hate. Under 2000 exist, scattered over China, and rarely is more than one met at once.', NULL, 12, '{"attacks":8,"initiative":1,"strike":3,"parry":3,"disarm":2,"pull":5}', '+2 to save vs possession (the book''s line is garbled), +8 save vs Horror Factor; its P.E. gives the saves vs magic and poison. Guns with no bonuses. The tail wields ancient weapons at half bonuses and guns at -4.', 'Speaks all languages, reads none. Gymnastics 80%, Climb 90%/85%, Dance 70%, Land Navigation 60%, Recognize Weapon Quality 80%, Trap/Mine Detection 60%, W.P. Blunt, W.P. Sword or Ancient Weapon of choice, three Technical or Wilderness skills of choice 60%. Skills do not improve.', 'Nightvision 600 ft (183 m), sees the invisible. Leaps 20 ft (6.1 m) up and 30 ft (9.1 m) across; climbs at its running speed, 70% +2% per level. Immune to most S.D.C. weapons, jade excepted, and to disease, raw or rotten meat and cold, magical cold and ice included. Bio-regeneration: 4D6 M.D. each melee round (double at ley lines or wherever negative energy gathers), not at all in places of positive chi; a lost limb is back overnight. Active day or night, though it likes to sleep from two in the afternoon to seven or eight in the evening. Its prehensile tail holds and carries things and does skills at half proficiency in twice the time. VULNERABILITIES: bold, defiant, aggressive and bloodthirsty. S.D.C. jade weapons do their damage as M.D. It cannot swim and in deep water sinks and drowns, so it shuns boats and bridges over deep water (shallows and slow streams do not trouble it), though in a rage it may forget. Fire, magic, psionics and M.D. weapons do normal damage.', 'Aura of Power (4), Energy Bolt (5), Fire Bolt (7), Lantern Light (1), Magic Shield (6), Mystic Fulcrum (5), See Aura (6), Sense Evil (2), Turn Dead (6). Demonic curses: none.', 'None', '11-14 ft (3.3 to 4.2 m)', '700-1000 lbs (315 to 450 kg), all muscle', 'Unknown; 1000 years at least, perhaps immortal', 'China, the mountains and caverns above all, in a cave or a stone tower or castle close to a village; now and then other Asian mountains', 'None: a loner unless a stronger being forces it, though it keeps 3-8 lackeys (Goblins, evil Faerie Folk, lesser demons or ugly D-Bees) to whom it has no loyalty', 'Humans, whom it hates and eats along with their livestock; Fox Spirits and Monkey Spirits. It dislikes other demons and its own kind, and yields only to greater power', NULL, 'A huge, white-furred brute of small wit and savage temper that carries off beautiful women as slaves and lords it over mountain villages. It lives alone, bows only to something stronger and hungers for magic items.', 'Rifts World Book 24: China 1 p.126-128'),
('yaksha', 'Yaksha', 'demon', 'rifts', 0, 'Principled (3%), Scrupulous (15%), Unprincipled (15%), Anarchist (15%), Miscreant (25%), Diabolic (17%) or Aberrant (10%)', '{"IQ":"1D6+11","ME":"1D6+14","MA":"1D6+12","PS":"1D4+25","PP":"1D6+15","PE":"1D6+16","PB":"1D6+9","Spd":"1D6x10"}', NULL, NULL, '1D6x100+200', '2D4x100', '2D6x10+40', 'Also known as the Tiger. P.S. is Supernatural. Equivalent level 1D6+2 (the book''s label is Effective Level of Experience). About a third of the race, the Punyajanas, are gentle scholars rather than evil. Killed at 50 M.D.C. below zero or by beheading; short of that its regeneration brings it back within minutes.', NULL, 14, '{"attacks":6,"initiative":2,"strike":3,"parry":3,"dodge":4,"disarm":2,"pull":3}', 'Two attacks per melee by magic. +8 save vs Horror Factor, +2 save vs possession, +2 on every other save. +2 strike on an aimed shot with its two modern W.P.s. Favours Psi-Sword and Psi-Shield and sword-type weapons; may wear armor and use high-tech weapons and vehicles.', 'Speaks all languages; literate in Chinese and Dragonese/Elven 98% and in two other languages of choice 90%. Basic and Advanced Math 98%, Anthropology 70%, Art 35%, Calligraphy 60%, Climb 80%/70%, Computer Operation 80%, Dance 90%, Disguise 80%, Escape Artist 60%, History: China 70%, Horsemanship: General 75%, Intelligence 80%, Land Navigation 60%, Lore: Demons and Monsters 90%, Performance 75%, Pilot Vehicle (two of choice) 70%, Radio: Basic 85%, Seduction 50%, Sing 75%, Streetwise 60%, Swim 60%, Ventriloquism 80%, Whittling and Sculpting 60%, two modern W.P.s (guns) of choice. Skills do not improve.', 'A hawk''s sight reaching five miles (8 km); nightvision 1000 ft (305 m); sees the invisible. Follows a scent at 50%, +10% when it is blood. Dimensional teleport 45%. Bio-regeneration: 2D6 M.D. each melee round. S.D.C. fire and heat do nothing; M.D. plasma and magical fire or cold do half damage. Star Flight: becomes a streak of energy like a falling star and arrives one melee round (15 seconds) later at any spot it has been to before or can see, sight being five miles (8 km). Tiger form, white or ordinary and large: +20% tracking by smell, +10% Climb and Swim, Prowl 65%, Blend 50%, leaps 30 ft (9.1 m) up and 60 ft (18.3 m) across from a standstill, half again with a run. Human form and impersonation: copies a particular person at 96% with the subject in front of it, 82% for someone it knows well or has in photographs, video or digital images (+8% from a 3-D hologram), 40% from memory alone; copies a voice at 94% if well known, 80% off a good recording, 30% from memory. Using Total Recall and Alter Aura on someone it has met and whose aura it studied, the disguise is 95% perfect. Alters its height anywhere from 1 to 10 ft (0.3 to 3 m). VULNERABILITIES: it habitually underrates humans and lesser creatures, to its cost. Silver S.D.C. weapons hurt it as M.D. (a silver dagger''s 1D6 S.D.C. is 1D6 M.D.). Psionics, magic and most M.D. weapons do normal damage.', 'All Russian Nature Magic (Rifts Book of Magic p.168-175), plus: Aura of Death (12), Aura of Power (4), Armor Bizarre (15), Armor of Ithan (10), Death Trance (1), Carpet of Adhesion (10), Charismatic Aura (10), Charm (12), Fear (5), Eyes of Thoth (8), Fools Gold (10), Forcebonds (25), Frostblade (15), Globe of Silence (20), Heal Wounds (10), Ley Line Fade (20), Magic Net (7), Magic Pigeon (20), Magic Warrior (60), Mask of Deceit (15), Mend the Broken (10+), Multiple Image (7), Mystic Alarm (5), Negate Mechanics (20), Negate Poison (5), Reflection (7), See Wards (20), See in Magic Darkness (125), Speed of the Snail (50), Sub-Particle Acceleration (20), Words of Truth (15). Demonic curses: Bad Luck, Headaches and Fleas.', 'Master Psychic (Mind Melter): all Physical and Sensitive powers and all Telemechanic powers, plus Detect Psionics (6), Psychic Diagnosis (4), Psychic Purification (8), Bio-Manipulation (10), Electrokinesis (varies), Empathic Transmission (6), Hypnotic Suggestion (6), Mentally Possess Others (30), Mind Bolt (10), Mind Wipe (special), P.P.E. Shield (10), Psi-Sword (30), Psychic Body Field (30)', '6-10 ft (1.8 to 3 m) naturally; can be anything from 1 to 10 ft (0.3 to 3 m)', 'About 700 lbs (315 kg) at its natural height', NULL, 'China and Southeast Asia for the most part, though one may turn up anywhere on Earth or in the Megaverse', 'Other Tigers and Raksashas, never for long; it commands lesser demons, Goblins, monsters and humans, and serves a Yama King only as his right hand', 'The Demons of Hades, Deevils, elder gods, Gods of Light, heroes and all forces of good; its Raksasha cousins are feared rivals. Hates scholars, artists and magic users; humans are slaves and food', NULL, 'A tiger-headed shape-changer and kin to the Raksasha, polished in manner and jealous of human art, science and magic. It plots from behind a throne and eats people, though roughly a third of its race are mild scholars.', 'Rifts World Book 24: China 1 p.128-131'),
('ying-hsuan-shang', 'Ying Hsuan Shang', 'demon', 'rifts', 0, 'Anarchist (20%), Miscreant (40%), Diabolic (20%) or Aberrant (20%)', '{"IQ":"1D6+12","ME":"1D6+12","MA":"1D6+10","PS":"1D6+30","PP":"1D6+18","PE":"1D6+20","PB":"1D6+10","Spd":"1D6+30"}', NULL, NULL, '2D4x100', 'PEx10', '3D4x10+60', 'Also known as the Demon Eye. P.S. is Supernatural. M.D.C. +6D6x10 per level of experience; P.P.E. +1D6x10 per level. Spd is about 22 mph (35 km), doubled as a leopard. Sunlight halves M.D.C., P.P.E., I.S.P. and how far it sees. Equivalent level 1D6+2. Male or female, 50% each. At zero M.D.C., or down to 30 below, it shrinks into a white kitten of 2D6+6 M.D.C.; only killing the kitten destroys it, leaving a green mist gone in 1D4 minutes.', NULL, 15, '{"attacks":12,"initiative":4,"strike":6,"parry":6,"dodge":1,"disarm":6,"pull":3,"roll":3}', 'The 12 attacks do not change with experience. A spell counts as four attacks. +3 to entangle. +2 save vs all magic; +8 save vs Horror Factor and possession. The eye''s lightning strikes at +6 and takes no other bonus. Weapons are used with no W.P. bonus.', 'Speaks all languages; reads basic Chinese 50%. Basic Math 98%, Blend 60%, Camouflage 70%, Climb 98%/90%, Detect Ambush 75%, Detect Concealment 80%, Dowsing 60%, Find Contraband 90%, Gemology 80%, Horsemanship: Exotic Animals 70%, Intelligence 80%, Interrogation 80%, Land Navigation 85%, Pilot: Canoe/Kayaking 70%, Pilot: Sail Boat 75%, Prowl 60%, Salvage 75%, Surveillance Systems 75% (tailing only), Track Humanoids 70%, Track Animals 75% (+10% as a leopard), Trap/Mine Detection 80%, two Wilderness skills of choice, two Espionage or Rogue skills of choice 60%. Skills do not improve.', 'Leaps 30 ft (9.1 m) up and 60 ft (18.3 m) across from a standstill, twice that with a run. Dimensional teleport 20% +5% per level. Immune to disease and to S.D.C. weapons other than silver; fire, heat and cold do half damage. Bio-regeneration: 2D6 M.D. each melee round (double at ley lines or wherever negative energy gathers), not at all in places of positive chi; a lost eye, tail, foot, leg, arm or hand grows back in four hours. Active at night and weaker by day; rests 3 hours in 24 and can skip sleep for a week. Sight: picks out something the size of a rabbit at five miles (8 km), nightvision 2000 ft (610 m), sees the invisible and every spectrum of light, and no glare or Blinding Flash can blind it. Third-eye lightning reaches 3000 ft (914 m). Black Vapor form, one attack to take and one to leave: moves at half speed or on the wind, untouchable by physical attacks but unable to attack or use powers, +10% Prowl. Leopard form, black or white: running speed doubled, leaps half again as far, climbs as fast as it runs, tracks by scent 80% (+10% on blood). VULNERABILITIES: sunlight weakens it, as in the pools note. Silver S.D.C. weapons hurt it as M.D. (a silver spear''s 2D6 S.D.C. is 2D6 M.D.). Psionics, magic, explosives and man-made M.D. weapons do normal damage; plasma, like fire, half. Water is harmless, but it avoids swimming and baths.', 'Blind (6), Calling (8), Charm (8), Domination (10), Concealment (6), Detect Concealment (6), Dispel Magic Barriers (20), Distant Voice (10), Escape (8), Eyes of Thoth (8), Eye of the Wolf (25), Globe of Daylight (2), Lantern Light (1), Ley Line Time Capsule (15), Ley Line Time Flux (80), Ley Line Transmission (30), Lifeblast (15), Locate (30), Invisibility: Simple (6), Memory Bank (12), Mute (50), Rift Teleportation (200), Seal (7), Second Sight (20), See Aura (6), See in Magic Darkness (125), Sense Magic (4), Teleport: Lesser (15), Transferal (50), Words of Truth (15). Demonic curses: Feebleness.', 'Major Psychic: all Sensitive powers, plus Detect Psionics (6), Psychic Diagnosis (4), Psychic Omni-Sight (15), Mind Bond (10), Telemechanic Mental Operation (12)', '8 ft (2.4 m)', '600 lbs (270 kg)', 'Presumed immortal', 'China, and to a lesser degree Southeast Asia and India; anywhere its master sends it', 'Works for the Yama Kings and other powers, from mortal dark sorcerers upward', 'Whoever stands between it and its quarry, and its master''s foes. Dislikes priests, monks, heroes and those who serve the Celestial Court or the Gods of Light', NULL, 'A leopard-headed demon with six arms and three eyes, kept by greater powers as a tireless tracker, scout and spy. The chase is all it cares about, and its third eye throws lightning.', 'Rifts World Book 24: China 1 p.131-132'),
('mo-lo', 'Mo-Lo', 'demon', 'rifts', 0, 'Miscreant (40%), Diabolic (55%) or Aberrant (5%)', '{"IQ":"1D6+24","ME":"1D6+22","MA":"1D6+20","PS":"1D6+40","PP":"1D6+15","PE":"1D6+22","PB":"1D6+4","Spd":"1D6+10"}', NULL, NULL, '1D4x1000', '1080', 'MEx10', 'Also known as the Mara, He Who Kills. Race: a Demon Lord, a corruptor and destroyer. P.S. is Supernatural. M.D.C. +1D6x100 per level of experience; P.P.E. +2D6x10 per level. Sunlight and daytime halve M.D.C., P.P.E., I.S.P., bonuses and attacks. Equivalent level 1D6+5. Always male. Taken past 100 M.D.C. below zero it becomes a Preta, a hungry ghost that roams the eight Hells for two hundred years and then re-forms. To kill it, bring it below zero but no further than -100, sever every arm except two and cast them into a lake, river or the sea, and have a priest give the body a proper burial.', NULL, 17, '{"attacks":18,"initiative":4,"strike":8,"parry":10,"dodge":2,"disarm":4}', 'The 18 attacks do not change with experience. No more than two spells a round, each counting as three attacks. +8 to entangle. +1 save vs all magic, +4 save vs mind control; immune to illusion, Horror Factor and possession. Three tentacles pin one opponent. Its usual weapon is a giant sword.', 'Speaks all languages; reads every Chinese language, Hindu/Indian, Dragonese and two languages of choice 94%. All Rogue skills and all Lores 75%, Basic Math 98%, Advanced Math 90%, Dance 90%, Dowsing 90%, Gemology 90%, History: China 90%, Navigation 95%, two Domestic and two Science skills of choice 75%. Skills do not improve.', 'Keen sight, nightvision 3000 ft (914 m), sees the invisible and through magical darkness. Needs no air and lasts forever in a vacuum. Dimensional teleport 80% +1% per level. Immune to S.D.C. weapons other than bone or silver, and to possession, disease and ordinary heat and cold (the M.D. kinds do full damage); poison has half its damage and duration. Bio-regeneration: 1D4x10 M.D. each melee round (double at ley lines or wherever negative energy gathers), not at all in places of positive chi. Weaker by day but free to appear at any hour. Resizes itself at will between 1 ft (0.3 m) and 25 ft (7.6 m). Takes the shape of any misshapen humanoid monster, many-armed as a rule, for as long as it likes, or of any predatory animal, the tiger by preference. Death Breath (also printed Breath of Death): a poison mist, six attacks, once an hour and never by day; roll 14 or better vs poison with no bonuses, or hold the breath 30 seconds at a cost of two attacks and -20% on skills, else lose half of current Hit Points or M.D.C. and fall into a coma, dying after one hour per point of P.E. unless healed. Disease Breath: one attack, one target, once per person each night; roll 16 or better vs non-lethal poison or hold the breath as above, else within two melee rounds (30 seconds) one illness is at full strength for 1D4+1 days: Pox, Fever, Numbness, Stomach Sickness, Headaches or a Minor Disorder. Fog Breath: four attacks, sent up to 200 ft (61 m), a 50 ft (15.2 m) radius that doubles with each full round of breathing up to one mile (1.6 km); sight is 3 ft (0.9 m), close combat is -2, strike, parry and dodge are -6 out to 9 ft (2.7 m) and shooting blind past that is -10. Stench Breath: 30 ft (9.1 m) radius; roll 16 or better vs non-lethal poison or retch, losing three attacks and initiative, and afterward -2 initiative, -20% skills and -20% Spd; a keen nose loses half its bonuses. Summons, each band doing one task: once in 24 hours two Ch-iang Shih, or 5 Shen Mo, or 9 Kuei or Preta; once in 24 hours 9 Goblins, or 3 Fox Faeries, or a pair of Monkey or Fox Spirits, none of them loyal; every 12 hours as many as 18 Lesser Demons (not Spirits), wholly loyal; every 24 hours as many as 6 Greater Demons, wholly loyal; once a day 1D6 of his Mara Asuras daughters. Summons weather through his magic. Spits lightning 3000 ft (914 m). VULNERABILITIES: greed, and a compulsion to spite the Gods of Light, keep the Mo-lo from real supremacy. S.D.C. weapons of bone, or of or plated in silver, do ten times their damage as M.D. (1D6 S.D.C. is 1D6x10 M.D.). Daylight halves him, as in the pools note. Psionics, magic and M.D. weapons do normal damage.', 'All spell invocations of levels 7-15, plus the Spells of Legend: Doppleganger Superior (1000), Metropolis (1600), Sanctuary (1500). Demonic curses: all.', 'Master Psychic: all Physical powers and all Super-Psionics, plus Telepathy (4; free when speaking with his daughters)', '25 ft (7.6 m); can shrink to as little as 1 ft (0.3 m)', '3 tons', 'Presumed immortal', 'China above all, but he may go anywhere in the Megaverse', 'Every Lesser Demon and most Greater Demons obey him; Ghosts, Goblins and the undead are cowed; evil humans may worship him, and other dark gods, Demon Lords, evil dragons and monsters may side with him', 'Everything good, pious or beautiful, the Celestial Court and the Gods of Light and their followers first. The Yama Kings are rivals he sometimes joins against the Court; mortals are pawns and toys', NULL, 'A towering lord of death and the moon, one of eighty-eight, with many arms and tentacles and an enslaved elephant spirit for a mount. He exists to corrupt and torment and to thwart the Gods of Light, working chiefly through his daughters.', 'Rifts World Book 24: China 1 p.133-136'),
('mara-asuras', 'Mara Asuras', 'demon', 'rifts', 0, 'Miscreant (40%), Diabolic (50%) or Aberrant (10%)', '{"IQ":"1D6+15","ME":"1D6+15","MA":"1D6+15","PS":"1D6+20","PP":"1D6+15","PE":"1D6+15","PB":"1D6+20","Spd":"1D6+15"}', NULL, NULL, '2D6x100+88', '1D4x100', '2D6x10+88', 'Also known as Daughter of the Mo-lo and Death''s Daughter. Race: a Greater Demon, among the mightiest of them. P.S. is Supernatural. P.P.E. +1D6x10 per level of experience. Spd is running; she also rides the wind. P.B. is never under 21 in human form. The Horror Factor is printed as Horror/Awe: awe as a beauty, horror as the withered corpse. Sunlight and daytime halve M.D.C., P.P.E., I.S.P., bonuses and attacks. Usually wholly loyal to the Mo-lo who sired her. Equivalent level 1D6+3. Female only. Killed at 50 M.D.C. below zero, or by drowning.', NULL, 15, '{"attacks":7,"initiative":3,"strike":6,"parry":2,"dodge":2,"disarm":2,"pull":2,"roll":2}', 'A spell counts as two attacks. +2 save vs all magic; immune to magic illusions, Horror Factor and possession. Guns are used with no W.P. bonus.', 'Speaks all languages; reads any Chinese script 90%. Basic Math 90%, Climb 70%/60%, Computer Operation 70%, Concealment 80%, Cook 90%, Dance 90%, Floral Arrangement 90%, Law 70%, Lore: All 75%, Poetry 90%, Prowl 60%, Sing 90%, Intelligence 80%, Land Navigation 70%, Navigation 70%, Pick Locks 80%, Pick Pockets 80%, Radio: Basic 75%, Seduction 90%, Streetwise 60%, Surveillance Systems 70% (80% tailing), three Rogue or Technical skills of choice 60%. Skills do not improve.', 'Nightvision 1000 ft (305 m), sees the invisible. Goes invisible whenever she likes, as the Lesser Invisibility spell. Her dimensional teleport succeeds 50% of the time, +4% for each level, and 100% when the destination is her father''s feet. Immune to disease; cold and poison do half damage. Bio-regeneration: 1D6 M.D.C. a minute, or one point each melee round. Rides the wind: twice the wind''s speed when flying with it, half its speed when flying against it. Knows when rain is on the way and how hard it will fall. Human form, for as long as she likes: a lovely woman of any adult age, P.B. 21 or more, whom no psionic power, spell or insight (See Aura included) reveals as a demon; only her conduct gives her away, and she may be taken for a Fox Spirit or Fox Faerie. A mirror, water or rain shows the corpse she really is. VULNERABILITIES: she loathes water and cannot swim; held under, she drowns in as many minutes as her P.E. (16-21 minutes). S.D.C. weapons of bone, or of or plated in silver, do ten times their damage as M.D. (1D6 S.D.C. is 1D6x10 M.D.). Daylight halves her, as in the pools note. Psionics, magic and M.D. weapons do normal damage.', 'Agony (20), Banishment (65), Beat Insurmountable Odds (40), Blind (6), Blinding Flash (1), Charm (12), Charismatic Aura (10), Cloak of Darkness (6), Compulsion (20), Constrain Being (20), D-Step (50), Death Curse (special), Deathword (70), Dessicate the Supernatural (50), Domination (10), Dispel Magic Barriers (20), Energy Bolt (5), Energy Disruption (12), Energy Field (10), Energy Sphere (120), Expel Demons (35), Fire Ball (10), Force Bonds (25), Frequency Jamming (15), Giant (80), Havoc (70), Id Alter Ego (130), Impervious to Energy (20), Lantern Light (1), Life Drain (25), Locate (30), Magic Pigeon (20), Magic Warrior (60), Manipulate Objects (2+), Mask of Deceit (15), Mute (50), Mystic Alarm (5), Mystic Portal (60), Reality Flux (75), Reduce Self (20), Re-Open Gateway (180), Restore Life (275), Rift Teleportation (200), Shadow Meld (10), Shatter (5), Sickness (50), Summon and Control Animals (125), Summon Greater Familiar (140), Summon Shadow Beast (140), Time Slip (20), Transferal (50), Wall of Not (70), Watchguard (10). Spell of Legend: Doppleganger Superior (1000). Demonic curses: Ancestors, Forefather, Heritage, Plague, Pox, Wasting.', 'Master Psychic (on par with the Mind Melter): all Mind Bleeder abilities, Telepathy (4) and all Super-Psionics', '5-6 ft (1.5 to 1.8 m); also has the spells Giant and Reduce Self', '90-140 lbs (40.5 to 63 kg)', NULL, 'China above all, but she may be sent anywhere in the Megaverse', 'Most of China''s Lesser Demons (not Spirits) must obey her, as must Kinnaras, Mahoragas, the Red Child and the White Monkey; Ghosts, Vampires, Goblins and mortals submit out of fear for as long as she holds power', 'Her father''s foes: the Gods of Light, the Celestial Court and those who serve them. She envies beautiful people and ruins beauty; most dislike the Yama Kings as rivals, and mortals are pawns and toys', NULL, 'A daughter of a Mo-lo who passes for a pale, lovely maiden while being a withered corpse underneath. She seduces and ruins heroes and holy men for her father, spies and kills for him, and plots against her own sisters.', 'Rifts World Book 24: China 1 p.136-138'),
('shih-ju-shen', 'Shih-Ju Shen', 'demon', 'rifts', 0, 'Diabolic (50%) or Miscreant (50%)', '{"IQ":"1D6+18","ME":"1D6+18","MA":"1D6+18","PS":"1D6+24","PP":"1D6+16","PE":"1D6+16","PB":"1D4","Spd":"1D6+18"}', NULL, NULL, '3D4x100', '1D6x100', 'MEx10', 'Also known as the Look-Flesh Demon. Race: a Demon Lord. P.S. is Supernatural. M.D.C. +1D4x10 per level of experience; P.P.E. +1D6x10 per level; I.S.P. +1D4x10 per level. Spd is tripled as a stag. Its high M.A. and fortune telling make it less horrifying than it might be. Sunlight and daytime, or Globe of Daylight after one minute, halve attacks, combat bonuses, M.D.C., P.P.E. and I.S.P. Equivalent level 2D4+4. Male. Killed at 100 M.D.C. below zero, and said to return with the next harvest moon unless its mouth is filled with dirt, rubies are laid on its eyes and a priest buries it properly; rumour has it that even this only suspends it.', NULL, 14, '{"attacks":6,"initiative":1,"strike":2,"parry":2,"dodge":1,"disarm":1,"pull":2}', 'Not a fighter. The six attacks do not change with experience. A spell counts as three attacks. +2 save vs all magic; immune to illusions, Horror Factor and possession. Man-made weapons are used with no W.P. bonus.', 'Speaks all languages; reads all Chinese writing 98%. Basic Math 98%, Calligraphy 80%, Concealment 80%, Dance 80%, Escape Artist 90%, Find Contraband 75%, Forgery 80%, History: China 90%, Holistic Medicine 80%, Intelligence 80%, Interrogation Techniques 80%, Land Navigation 80%, Poetry 90%, Performance 90%, Prowl 50%, Streetwise 80%, Swim 80%, Tracking (humanoids) 80%, all Lores 80%, two Wilderness or Espionage skills of choice 80%. The skills hold in either body. Skills do not improve.', 'Nightvision 1000 ft (305 m). Dimensional teleport, with no percentage printed. Immune to S.D.C. weapons other than stone or bone, and to cold, poison and disease. Bio-regeneration: 3D6 M.D. each melee round (double at ley lines or wherever negative energy gathers), not at all in places of positive chi. Shows itself by day in a weakened state; rests 2-3 hours in 24 and can skip sleep for a week. Resizes itself at will from 5 ft (1.5 m) to 20 ft (6.1 m). Three giant white animal forms: an alligator 30 ft (9.1 m) long that swims at 90% and breathes water; a stag 8 ft (2.4 m) at the shoulder with triple running speed, leaps of 15 ft (4.6 m) up and 60 ft (18.3 m) across, and +1D6 M.D. on kicks and antler strikes; a tiger 10 ft (3 m) long with Prowl 60%, tracking by smell 60% (+15% on blood) and leaps of 30 ft (9.1 m) up and 60 ft (18.3 m) across, half again with a run. Human form, male or female, and flawless impersonation of a particular person, voice, face and manner, both as the Red Child does them. Show the Future: displays a person''s future in its palm, to that person alone or to everyone present, and can send a shared vision as a dream up to 200 miles (320 km); it chooses and slants what is seen. True Vision: no illusion fools it, and it knows at once a disguised Fox Faerie, Monkey Spirit, Fox Spirit or undead, and any god, demon, goblin or spirit wearing an animal''s shape. VULNERABILITIES: S.D.C. weapons of stone or bone do double their damage as M.D. Daylight halves it, as in the pools note. Psionics, magic and M.D. weapons do normal damage.', 'Apparition (20), Calling (8), Climb (3), Compulsion (20), Create Water (15), Create Wood (10+), Create Steel (68), Escape (8), Fear (5), Hallucination (30), Horrific Illusion (10), Id Alter Ego (130), Illusion Booster (15), Illusion Manipulation (25+), Illusory Forest (45+), Illusory Terrain (55+), Illusory Wall (15+), Manipulate Objects (2+), Mask of Deceit (15), Memory Bank (12), Multiple Image (7), Oracle (30), Reality Flux (75), Reflection (7), Second Sight (20), Sheltering Force (20), Spoil (20), Swim as a Fish (6). Demonic curses: Ancestors, Animal Disease, Barrenness, Drought, Interesting Life, Hunger, Minor Disorder.', 'Master Psychic (on par with a Mind Melter): all Sensitive powers and all Super-Psionics', '20 ft (6.1 m); can be as small as 5 ft (1.5 m)', NULL, 'Presumed immortal; thought to be older than the Yama Kings', 'China, at times Korea, Japan, Russia and India; it may go anywhere on Earth or in the Megaverse', 'Anyone might be one, the selfish and evil most often. Lesser and Greater demons act as its agents, by preference Fox Faeries, Headless Ones, Kinnaras, Mahoragas and the Red Child; evil humans, forest spirits and Goblins are used too', 'The wise and the beings of Light and order fear and dislike it. A thing of chaos with a hidden purpose of its own, it has now and then aided the good; humans are pawns and toys', NULL, 'A hippopotamus-headed giant, possibly a fallen elder god, that can pass for human and shows mortals chosen glimpses of what awaits them. It deals in half-truths to corrupt, to kill hope and to steer events from behind a throne, for reasons no one can read.', 'Rifts World Book 24: China 1 p.138-141');
