-- Rifts World Book 24: China 1 - its bestiary and its notable NPCs.
-- 16 creatures (migration 074) and 0 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~062-china-1-greater-demons.sql
--
-- Written by scripts/bestiary-sql.mjs from 3 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.




-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 16 creatures are in' AS assertion, count(*) AS got, 16 AS want
  FROM creatures WHERE slug IN ('kinnaras', 'kou-ching', 'mahoragas', 'monkey-spirit', 'naga', 'naga-spawn', 'water-goblin', 'water-devil', 'red-child-demon', 'shen-wu', 'white-monkey', 'yaksha', 'ying-hsuan-shang', 'mo-lo', 'mara-asuras', 'shih-ju-shen');
SELECT 'and 1 of them are playable' AS assertion, count(*) AS got, 1 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('kinnaras', 'kou-ching', 'mahoragas', 'monkey-spirit', 'naga', 'naga-spawn', 'water-goblin', 'water-devil', 'red-child-demon', 'shen-wu', 'white-monkey', 'yaksha', 'ying-hsuan-shang', 'mo-lo', 'mara-asuras', 'shih-ju-shen');
SELECT 'the creatures carry 77 attacks' AS assertion, count(*) AS got, 77 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('kinnaras', 'kou-ching', 'mahoragas', 'monkey-spirit', 'naga', 'naga-spawn', 'water-goblin', 'water-devil', 'red-child-demon', 'shen-wu', 'white-monkey', 'yaksha', 'ying-hsuan-shang', 'mo-lo', 'mara-asuras', 'shih-ju-shen');

